def resolve_ref_path(raw_path: str, base_dirs: List[Path]) -> Optional[Path]:
    p = Path(raw_path)
    if p.is_absolute():
        return p if p.is_file() else None
    for base in base_dirs:
        cand = (base / p).resolve()
        if cand.is_file():
            return cand
    return None

